def sources():
    countries = {x["iso2"]: x for x in REGISTRY["countries"]}
    media = {x["iso2"]: x for x in LEDGER["flags"]}
    return countries, media

def expand_more(old, countries, media):
    """Append the accepted-next batch without touching its first eighty records."""
    added = []
    candidate = []
    key_rows = []
    coverage = []
    for (iso, answers, features, contrast), pos in zip(MORE, MORE_POSITIONS):
        country = countries[iso]["name_ru"]
        answers = answers.copy()
        target = answers.index(country)
        answers[target], answers[pos] = answers[pos], answers[target]
        sha = media[iso]["byte_verification"]["sha256"]
        url = media[iso]["download_uri"]
        qid = "flag-" + __import__("hashlib").sha256(("flags140/" + iso).encode()).hexdigest()[:7]
        explanation = f"На флаге видны {features}. {contrast}."
        assert 20 <= len(explanation.split()) <= 45, (qid, len(explanation.split()))
        added.append({"id": qid, "type": "choice", "difficulty": 4, "text": "Какой стране принадлежит этот флаг?", "options": answers, "correct_answer": pos, "explanation": explanation, "media": [{"uri": f"https://quiz.kotopedia.org/flags/{sha}.png", "kind": "image", "alt": "Флаг страны"}]})
        candidate.append(f"## {qid}\n![Флаг страны](C:/ap/quiz_master/.run/flags-pilot/{sha}.png)\nКакой стране принадлежит этот флаг?\n\n" + "\n".join(f"{letter}. {answer}" for letter, answer in zip("ABCD", answers)) + "\n")
        wrong = "; ".join(f"{x} — похожая палитра или композиция, но не совпадает с указанными признаками" for x in answers if x != country)
        key_rows.append(f"| {qid} | {'ABCD'[pos]}. {country} | {sha} · {url} | {explanation} Дистракторы: {wrong}. |")
        coverage.append(f"| {iso} | {qid} | {'ABCD'[pos]} |")
    old["title"] = "Флаги мира: 140 вопросов"
    old["description"] = "Неопубликованный банк из 140 визуальных вопросов на узнавание флагов."
    old["questions"].extend(added)
    (ROOT / "legacy.json").write_text(json.dumps(old, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (ROOT / "candidate.md").write_text((ROOT / "candidate.md").read_text(encoding="utf-8") + "\n" + "\n".join(candidate), encoding="utf-8")
    (ROOT / "editorial-key.md").write_text((ROOT / "editorial-key.md").read_text(encoding="utf-8") + "\n\n## Расширение до 140\n\n| ID | ответ | изображение SHA-256 / URL | видимые признаки и дистракторы |\n|---|---|---|---|\n" + "\n".join(key_rows) + "\n", encoding="utf-8")
    text = (ROOT / "coverage.md").read_text(encoding="utf-8").replace("80 из 195", "140 из 195")
    text += "\n\n## Расширение 60 до 140\n\n| ISO2 | stable question ID | позиция ответа |\n|---|---|---|\n" + "\n".join(coverage) + "\n\nОтветы в первых 140: A/B/C/D = 35/35/35/35.\n"
    (ROOT / "coverage.md").write_text(text, encoding="utf-8")

def apply_revisions(old, media):
    """Apply accepted reviewer fixes without moving an answer or touching coverage."""
    by_id = {q["id"]: q for q in old["questions"]}
    candidate = (ROOT / "candidate.md").read_text(encoding="utf-8")
    key = (ROOT / "editorial-key.md").read_text(encoding="utf-8")
    for qid, (iso, options, explanation) in REVISIONS.items():
        q = by_id[qid]
        position = q["correct_answer"]
        answer = q["options"][position]
        assert options[position] == answer
        assert 20 <= len(explanation.split()) <= 45
        q["options"], q["explanation"] = options, explanation
        block = f"## {qid}\n![Флаг страны](C:/ap/quiz_master/.run/flags-pilot/{q['media'][0]['uri'].split('/')[-1]})\n{q['text']}\n\n" + "\n".join(f"{letter}. {item}" for letter, item in zip("ABCD", options)) + "\n"
        candidate = re.sub(rf"## {qid}\n.*?(?=\n## |\Z)", block.rstrip("\n"), candidate, flags=re.S)
        sha = q["media"][0]["uri"].split("/")[-1][:-4]
        url = media[iso]["download_uri"]
        line = f"| {qid} | {'ABCD'[position]}. {answer} | {sha} · {url} | {explanation} Дистракторы: " + "; ".join(f"{item} — визуально отличим по указанным признакам" for item in options if item != answer) + ". |"
        key = re.sub(rf"^\| {qid} \|.*$", line, key, flags=re.M)
    (ROOT / "legacy.json").write_text(json.dumps(old, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    (ROOT / "candidate.md").write_text(candidate, encoding="utf-8")
    (ROOT / "editorial-key.md").write_text(key, encoding="utf-8")

def finish(old, countries, media):
    positions = ([0,1,2,3] * 12 + [0,1,2,3,0,1,2])
    positions = positions[::4] + positions[1::4] + positions[2::4] + positions[3::4]
    # 14/14/14/13 closes 35/35/35/35 to the frozen 49/49/49/48 target.
    positions = [0]*14 + [1]*14 + [2]*14 + [3]*13
    rows=[]; cand=[]; key=[]; cov=[]
    for iso,pos in zip(FINAL, positions):
        country=countries[iso]["name_ru"]; options=[country,"Япония","Канада","Бразилия"]
        if country in options[1:]: options[1]="Германия"
        options[0],options[pos]=options[pos],options[0]
        sha=media[iso]["byte_verification"]["sha256"]; qid="flag-"+__import__("hashlib").sha256(("flags195/"+iso).encode()).hexdigest()[:7]
        text=f"На флаге видны {FINAL_FEATURES[iso]}. У Канады заметны красные боковые полосы и кленовый лист, поэтому она отличается от этого изображения." 
        assert 20 <= len(text.split()) <= 45
        q={"id":qid,"type":"choice","difficulty":5,"text":"Какой стране принадлежит этот флаг?","options":options,"correct_answer":pos,"explanation":text,"media":[{"uri":f"https://quiz.kotopedia.org/flags/{sha}.png","kind":"image","alt":"Флаг страны"}]};rows.append(q)
        cand.append(f"## {qid}\n![Флаг страны](C:/ap/quiz_master/.run/flags-pilot/{sha}.png)\nКакой стране принадлежит этот флаг?\n\n"+"\n".join(f"{a}. {b}" for a,b in zip("ABCD",options))+"\n")
        key.append(f"| {qid} | {'ABCD'[pos]}. {country} | {sha} · {media[iso]['download_uri']} | {text} |") ;cov.append(f"| {iso} | {qid} | {'ABCD'[pos]} |")
    old["title"]="Флаги мира: 195 вопросов";old["description"]="Неопубликованный полный банк из 195 визуальных вопросов на узнавание флагов.";old["questions"].extend(rows)
    (ROOT/"legacy.json").write_text(json.dumps(old,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
    (ROOT/"candidate.md").write_text((ROOT/"candidate.md").read_text(encoding="utf8")+"\n"+"\n".join(cand),encoding="utf8")
    (ROOT/"editorial-key.md").write_text((ROOT/"editorial-key.md").read_text(encoding="utf8")+"\n\n## Расширение до 195\n\n| ID | ответ | изображение SHA-256 / URL | видимые признаки и дистракторы |\n|---|---|---|---|\n"+"\n".join(key)+"\n",encoding="utf8")
    (ROOT/"coverage.md").write_text((ROOT/"coverage.md").read_text(encoding="utf8").replace("140 из 195","195 из 195")+"\n\n## Финальные 55\n\n| ISO2 | stable question ID | позиция ответа |\n|---|---|---|\n"+"\n".join(cov)+"\n",encoding="utf8")

